// SPDX-License-Identifier: MIT
pragma solidity 0.8.4;

import { IDepositHandler } from "./IDepositHandler.sol";

interface IPaymentModule is IDepositHandler {
    struct PaymentHolder {
        address tokenAddress;
        uint256 amount;
        uint256 payment;
    }

    struct ProcessPaymentParams {
        address vault;
        address user;
        address referrer;
        FungibleTokenDeposit[] fungibleTokenDeposits;
        NonFungibleTokenDeposit[] nonFungibleTokenDeposits;
        MultiTokenDeposit[] multiTokenDeposits;
        bool isVesting;
    }

    function processPayment(ProcessPaymentParams memory params) external payable;
}

contracts/locker/interfaces/IPricingModu.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.4;

import { IDepositHandler } from "../interfaces/IDepositHandler.sol";

interface IPricingModule is IDepositHandler {
    struct PriceInfo {
        address[] v2LpTokens;
        uint256[] v2LpAmounts;
        V3LPData[] v3LpTokens;
        uint256 usdtAmount;
    }

    /**
     * @notice Get price of vault creation.
     * @param user Address of vault creator.
     * @param fungibleTokenDeposits Array of fungible token deposits
     * consisting of addresses and amounts.
     * @param nonFungibleTokenDeposits Array of non-fungible token deposits
     * consisting of addresses and IDs.
     * @param multiTokenDeposits Array of multi token deposits consisting of
     * addresses, IDs and their corresponding amounts.
     * @return A four-item tuple consisting of an array of LP token addresses,
     * an array of the corresponding required payment amounts, an array of V3LPData, and the amount
     * of USDT required.
     */
    function getPrice(
        address user,
        FungibleTokenDeposit[] memory fungibleTokenDeposits,
        NonFungibleTokenDeposit[] memory nonFungibleTokenDeposits,
        MultiTokenDeposit[] memory multiTokenDeposits,
        bool isVested
    ) external view returns (PriceInfo memory);

    function priceDecimals() external view returns (uint8);
}

contracts/locker/interfaces/IDepositHand.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.4;

interface IDepositHandler {
    struct FungibleTokenDeposit {
        address tokenAddress;
        uint256 amount;
        bool isLP;
    }

    struct NonFungibleTokenDeposit {
        address tokenAddress;
        uint256 tokenId;
    }

    struct MultiTokenDeposit {
        address tokenAddress;
        uint256 tokenId;
        uint256 amount;
    }

    struct V3LPData {
        address tokenAddress;
        address token0;
        address token1;
        uint128 liquidityToRemove;
        uint24 fee;
    }
}

